INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (1,'<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<project xmlns=\"http://maven.apache.org/POM/4.0.0\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\nxsi:schemaLocation=\"http://maven.apache.org/POM/4.0.0 https://maven.apache.org/xsd/maven-4.0.0.xsd\">\n<modelVersion>4.0.0</modelVersion>\n<groupId>com.example</groupId>\n<artifactId>${project.name?lower_case}</artifactId>\n<version>0.0.1-SNAPSHOT</version>\n<name>${project.name}</name>\n</project>','pom.xml','pom-base');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (2,'plugins {\nid \'java\'\nid \'org.springframework.boot\' version \'${springBootVersion}\'\nid \'io.spring.dependency-management\' version \'1.1.5\'\n<#if project.framework == \"Vaadin\">\nid \'com.vaadin\' version \'${vaadinVersion}\'\n</#if>\n}\ngroup = \'com.example\'\nversion = \'0.0.1-SNAPSHOT\'\njava {\nsourceCompatibility = \'${project.javaVersion}\'\n}\nrepositories {\nmavenCentral()\n}\n<#if project.framework == \"Vaadin\">\ndependencyManagement {\nimports {\nmavenBom \"com.vaadin:vaadin-bom:${vaadinVersion}\"\n}\n}\n</#if>\ndependencies {\n// Core Dependencies\nimplementation \'org.springframework.boot:spring-boot-starter-data-jpa\'\nruntimeOnly \'com.h2database:h2\'\n<#if project.projectType == \"Web\" || project.projectType == \"API\" || project.framework == \"Spring MVC\" || project.framework == \"Spring Rest\">\nimplementation \'org.springframework.boot:spring-boot-starter-web\'\n</#if>\n<#if project.framework == \"Vaadin\">\nimplementation \'com.vaadin:vaadin-spring-boot-starter\'\n</#if>\n<#if project.framework == \"Spring Batch\">\nimplementation \'org.springframework.boot:spring-boot-starter-batch\'\n</#if>\n}\ntasks.named(\'test\') {\nuseJUnitPlatform()\n}','build.gradle','build-gradle');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (10,'<project xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xmlns=\"http://maven.apache.org/POM/4.0.0\"\nxsi:schemaLocation=\"http://maven.apache.org/POM/4.0.0 http://maven.apache.org/maven-v4_0_0.xsd\">\n<modelVersion>4.0.0</modelVersion>\n<groupId>com.example</groupId>\n<artifactId>.${project.name?lower_case}</artifactId>\n<packaging>war</packaging>\n<version>1.0</version>\n<name>${project.name?lower_case}</name>\n<url>http://maven.apache.org</url>\n<properties>\n<project.build.sourceEncoding>UTF-8</project.build.sourceEncoding>\n<maven.compiler.source>1.8</maven.compiler.source>\n<maven.compiler.target>1.8</maven.compiler.target>\n<jersey.version>2.22.4</jersey.version>\n<hibernate.version>4.3.6.Final</hibernate.version>\n</properties>\n<dependencies>\n<!-- Java EE API -->\n<dependency>\n<groupId>javax</groupId>\n<artifactId>javaee-api</artifactId>\n<version>7.0</version>\n<scope>provided</scope>\n</dependency>\n<dependency>\n<groupId>org.hibernate</groupId>\n<artifactId>hibernate-entitymanager</artifactId>\n<version>${r\"${hibernate.version}\"}</version>\n</dependency>\n<dependency>\n<groupId>org.hibernate</groupId>\n<artifactId>hibernate-jpamodelgen</artifactId>\n<version>${r\"${hibernate.version}\"}</version>\n</dependency>\n<dependency>\n<groupId>org.glassfish.jersey.core</groupId>\n<artifactId>jersey-client</artifactId>\n<version>${r\"${jersey.version}\"}</version>\n</dependency>\n<dependency>\n<groupId>org.glassfish.jersey.containers</groupId>\n<artifactId>jersey-container-servlet-core</artifactId>\n<version>${r\"${jersey.version}\"}</version>\n</dependency>\n<dependency>\n<groupId>org.glassfish.jersey.containers</groupId>\n<artifactId>jersey-container-servlet</artifactId>\n<version>${r\"${jersey.version}\"}</version>\n</dependency>\n<dependency>\n<groupId>com.fasterxml.jackson.core</groupId>\n<artifactId>jackson-annotations</artifactId>\n<version>2.17.0</version>\n</dependency>\n<dependency>\n<groupId>org.glassfish.jersey.media</groupId>\n<artifactId>jersey-media-multipart</artifactId>\n<version>${r\"${jersey.version}\"}</version>\n</dependency>\n<dependency>\n<groupId>org.glassfish.jersey.media</groupId>\n<artifactId>jersey-media-json-jackson</artifactId>\n<version>${r\"${jersey.version}\"}</version>\n</dependency>\n<dependency>\n<groupId>com.fasterxml.jackson.core</groupId>\n<artifactId>jackson-databind</artifactId>\n<version>2.17.0</version>\n</dependency>\n<dependency>\n<groupId>com.fasterxml.jackson.dataformat</groupId>\n<artifactId>jackson-dataformat-xml</artifactId>\n<version>2.17.0</version>\n</dependency>\n<!-- Logging -->\n<dependency>\n<groupId>org.apache.commons</groupId>\n<artifactId>commons-lang3</artifactId>\n<version>3.6</version>\n</dependency>\n<dependency>\n<groupId>commons-codec</groupId>\n<artifactId>commons-codec</artifactId>\n<version>1.5</version>\n</dependency>\n<dependency>\n<groupId>org.apache.logging.log4j</groupId>\n<artifactId>log4j-core</artifactId>\n<version>2.17.1</version>\n</dependency>\n<dependency>\n<groupId>org.apache.logging.log4j</groupId>\n<artifactId>log4j-api</artifactId>\n<version>2.17.1</version>\n</dependency>\n<dependency>\n<groupId>org.apache.logging.log4j</groupId>\n<artifactId>log4j-web</artifactId>\n<version>2.17.1</version>\n</dependency>\n<!-- Test -->\n<dependency>\n<groupId>junit</groupId>\n<artifactId>junit</artifactId>\n<version>4.12</version>\n<scope>test</scope>\n</dependency>\n<!-- JSON -->\n<dependency>\n<groupId>com.googlecode.json-simple</groupId>\n<artifactId>json-simple</artifactId>\n<version>1.1.1</version>\n</dependency>\n<!-- Lombok -->\n<dependency>\n<groupId>org.projectlombok</groupId>\n<artifactId>lombok</artifactId>\n<version>1.18.28</version>\n<scope>provided</scope>\n</dependency>\n<dependency>\n<groupId>org.apache.commons</groupId>\n<artifactId>commons-collections4</artifactId>\n<version>4.4</version>\n</dependency>\n</dependencies>\n<build>\n<finalName>ProbateCertificateGenerator.1.1.0.5</finalName>\n<plugins>\n<plugin>\n<groupId>org.apache.maven.plugins</groupId>\n<artifactId>maven-war-plugin</artifactId>\n<version>3.3.2</version>\n<configuration>\n<warSourceDirectory>src/main/webapp</warSourceDirectory>\n</configuration>\n</plugin>\n</plugins>\n<resources>\n<resource>\n<directory>src/main/resources</directory>\n<includes>\n<include>*.*</include>\n</includes>\n</resource>\n<resource>\n<directory>src/main/resources/META-INF</directory>\n<targetPath>META-INF</targetPath>\n</resource>\n<resource>\n<directory>src/main/resources/jasper-report/pic</directory>\n<includes>\n<include>*.*</include>\n</includes>\n</resource>\n<resource>\n<directory>src/main/resources/jasper-report</directory>\n<includes>\n<include>*.*</include>\n</includes>\n</resource>\n</resources>\n</build>\n</project>\n','pom.xml','pom-jasper-jee');
