INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (65,'Step 1: Enable WSL Feature\nOpen Settings (Windows key + I)\n\nGo to Apps → Optional Features\n\nClick More Windows features (at the bottom)\n\nCheck the boxes for:\n\nWindows Subsystem for Linux\n\nVirtual Machine Platform\n\nClick OK and restart your computer when prompted\n\nStep 2: Set WSL 2 as Default\nOpen PowerShell or Command Prompt as Administrator and run:\n\npowershell\nwsl --set-default-version 2','docler\\EnableWSLFeature.txt','Enable WSL Feature');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (66,'wsl --set-default-version 2','docker/Set WSL 2 as Default.txt','Set WSL 2 as Default');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (67,'Step 3: Install a Linux Distribution\nOpen Microsoft Store\n\nSearch for your preferred Linux distribution (Ubuntu, Debian, Kali Linux, etc.)\n\nClick Install\n\nStep 4: Set Up Your Distribution\nLaunch the installed Linux distribution from Start Menu\n\nCreate a username and password when prompted\n\nMethod 2: Using Command Line\nSingle Command Installation (Windows 11)\nOpen PowerShell or Command Prompt as Administrator and run:\n\npowershell\nwsl --install\nThis command will:\n\nEnable required features\n\nSet WSL 2 as default\n\nInstall Ubuntu Linux by default\n\nTo install a specific distribution:\npowershell\nwsl --install -d Ubuntu-22.04\n# or\nwsl --install -d Debian\n# or\nwsl --install -d Kali-Linux\nVerify Installation\nCheck your WSL installation with:\n\npowershell\nwsl --list --verbose','docker/Install a Linux Distribution.txt',' Install a Linux Distribution');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (69,'Additional Useful Commands\npowershell\n# Update WSL\nwsl --update\n\n# Set default version for new installations\nwsl --set-default-version 2\n\n# Check WSL status\nwsl --status\n\n# Shutdown WSL\nwsl --shutdown\n\n# List available distributions\nwsl --list --online','docker\\Useful Ubuntu WSL Commands.txt','Useful Ubuntu WSL Commands');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (70,'Update Ubuntu\nKeep your Ubuntu installation updated:\n\nbash\nsudo apt update\nsudo apt upgrade\nsudo apt autoremove\nTroubleshooting\nIf Ubuntu doesn\'t start properly:\n\npowershell\n# Reset Ubuntu (will remove all data!)\nwsl --unregister Ubuntu\nwsl --install -d Ubuntu\n\n# Check logs\nwsl --status\nIf you get \"WSL 2 requires an update\":\nDownload and install the WSL 2 Linux kernel update package from:\nhttps://aka.ms/wsl2kernel\n\nYour Ubuntu WSL installation is now complete! You can access it by typing ubuntu in Command Prompt or PowerShell, or by launching the Ubuntu app from Start Menu.','docker\\Update Ubuntu.txt','Update Ubuntu');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (73,'I\'ll help you install Docker on your Ubuntu WSL. Here are the methods:\n\nMethod 1: Install Docker Engine on Ubuntu WSL (Recommended)\nStep 1: Update package list\nbash\nsudo apt update\nsudo apt upgrade -y\nStep 2: Install required dependencies\nbash\nsudo apt install -y \\\n    ca-certificates \\\n    curl \\\n    gnupg \\\n    lsb-release\nStep 3: Add Docker\'s official GPG key\nbash\nsudo mkdir -p /etc/apt/keyrings\ncurl -fsSL https://download.docker.com/linux/ubuntu/gpg | sudo gpg --dearmor -o /etc/apt/keyrings/docker.gpg\nStep 4: Set up the repository\nbash\necho \\\n  \"deb [arch=$(dpkg --print-architecture) signed-by=/etc/apt/keyrings/docker.gpg] https://download.docker.com/linux/ubuntu \\\n  $(lsb_release -cs) stable\" | sudo tee /etc/apt/sources.list.d/docker.list > /dev/null\nStep 5: Install Docker Engine\nbash\nsudo apt update\nsudo apt install -y docker-ce docker-ce-cli containerd.io docker-compose-plugin\nStep 6: Add your user to the docker group\nbash\nsudo usermod -aG docker $USER\nStep 7: Start and enable Docker service\nbash\n# Start Docker service\nsudo service docker start\n\n# Enable Docker to start on boot\nsudo update-rc.d docker defaults','docker/Install Docker Engine on Ubuntu WSL (Recommended).txt','Install Docker Engine on Ubuntu WSL (Recommended)');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (74,'Method 2: Using Docker Desktop for Windows (Easier)\nStep 1: Install Docker Desktop for Windows\nDownload from: https://www.docker.com/products/docker-desktop/\n\nRun the installer\n\nEnable WSL 2 integration during installation\n\nStep 2: Configure WSL 2 Integration\nOpen Docker Desktop\n\nGo to Settings → Resources → WSL Integration\n\nEnable integration with your Ubuntu WSL distribution\n\nClick Apply & Restart\n\nStep 3: Verify Installation in WSL\nbash\ndocker --version\ndocker-compose --version\nVerify Docker Installation\nCheck Docker version:\nbash\ndocker --version\ndocker-compose --version\nTest Docker installation:\nbash\n# Run hello-world container\ndocker run hello-world\nUseful Docker Commands\nbash\n# Check Docker status\nsudo service docker status\n\n# Start Docker service\nsudo service docker start\n\n# Stop Docker service\nsudo service docker stop\n\n# View running containers\ndocker ps\n\n# View all containers\ndocker ps -a\n\n# View images\ndocker images\n\n# Remove all containers\ndocker rm $(docker ps -a -q)\n\n# Remove all images\ndocker rmi $(docker images -q)',' docker/Using Docker Desktop for Windows.txt',' Using Docker Desktop for Windows');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (77,'Configure Docker to Start Automatically\nOption A: Using systemd (if available in WSL)\nbash\nsudo systemctl enable docker\nsudo systemctl start docker','docker/Configure Docker to Start Automatically.txt','Configure Docker to Start Automatically');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (78,'Docker Compose Installation\nIf not installed with Docker Engine:\nbash\n# Install Docker Compose\nsudo curl -L \"https://github.com/docker/compose/releases/download/v2.20.0/docker-compose-$(uname -s)-$(uname -m)\" -o /usr/local/bin/docker-compose\nsudo chmod +x /usr/local/bin/docker-compose\n\n# Verify installation\ndocker-compose --version\nTroubleshooting\nIf you get permission denied:\nbash\n# Fix permissions\nsudo chmod 666 /var/run/docker.sock\n\n# Or better: add user to docker group and restart WSL\nsudo usermod -aG docker $USER\nwsl --shutdown\n# Then restart Ubuntu\nIf Docker service won\'t start:\nbash\n# Check logs\nsudo service docker status\njournalctl -u docker.service\n\n# Reset Docker\nsudo apt purge docker-ce docker-ce-cli containerd.io\nsudo rm -rf /var/lib/docker\nsudo rm -rf /var/lib/containerd\n# Then reinstall\nIf you have port conflicts:\nbash\n# Stop any conflicting services\nsudo service apache2 stop\nsudo service nginx stop\nWSL-Specific Configuration\nImprove performance by storing Docker data in WSL:\nbash\n# Create docker data directory\nsudo mkdir -p /etc/docker\nCreate or edit Docker daemon configuration:\nbash\nsudo nano /etc/docker/daemon.json\nAdd the following content:\n\njson\n{\n  \"data-root\": \"/mnt/wsl/docker-data\",\n  \"hosts\": [\"unix:///var/run/docker.sock\", \"tcp://0.0.0.0:2375\"]\n}\nTest Your Docker Installation\nbash\n# Run a test container\ndocker run -it ubuntu:20.04 /bin/bash\n\n# Run Nginx web server\ndocker run -d -p 80:80 nginx\n\n# Run MySQL database\ndocker run -d -p 3306:3306 --name mysql -e MYSQL_ROOT_PASSWORD=password mysql:8.0\nUsing Docker with GUI Applications\nIf you need to run GUI apps in Docker containers, set the display:\n\nbash\n# Set display for GUI apps\nexport DISPLAY=$(awk \'/nameserver / {print $2; exit}\' /etc/resolv.conf 2>/dev/null):0\n\n# Example: run Firefox in Docker\ndocker run -it -e DISPLAY=$DISPLAY -v /tmp/.X11-unix:/tmp/.X11-unix jess/firefox\nNow you have Docker installed and running in your Ubuntu WSL! You can use it to build, run, and manage containers just like on a native Linux system.','docker/Docker Compose Installation','Docker Compose Installation');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (79,'WSL-Specific Configuration\nImprove performance by storing Docker data in WSL:\nbash\n# Create docker data directory\nsudo mkdir -p /etc/docker','docker/WSL-Specific Configuration','WSL-Specific Configuration');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (80,'Create or edit Docker daemon configuration:\nbash\nsudo nano /etc/docker/daemon.json\nAdd the following content:\n\njson\n{\n  \"data-root\": \"/mnt/wsl/docker-data\",\n  \"hosts\": [\"unix:///var/run/docker.sock\", \"tcp://0.0.0.0:2375\"]\n}','docker/Create or edit Docker daemon configuration.txt','Create or edit Docker daemon configuration:');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (81,'Test Your Docker Installation\nbash\n# Run a test container\ndocker run -it ubuntu:20.04 /bin/bash\n\n# Run Nginx web server\ndocker run -d -p 80:80 nginx\n\n# Run MySQL database\ndocker run -d -p 3306:3306 --name mysql -e MYSQL_ROOT_PASSWORD=password mysql:8.0','Test Your Docker Installation.txt','Test Your Docker Installation');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (89,'wsl --shutdown','Restart WSL.txt','Restart WSL');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (111,'# Check if Docker container is using the port\ndocker ps\nss -tulpn | grep 3306','docker/Check if Docker container is using the port.txt','Check if Docker container is using the port');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (112,'Yes! There are several ways to take your MySQL Docker container with its data to another machine. Here are the best methods:\n\nMethod 1: Docker Commit (Easiest)\nStep 1: Commit your container as a new image\nbash\n# Stop the container first\ndocker stop mysql\n\n# Commit the container to create a new image\ndocker commit mysql mysql-with-data\n\n# Verify the new image was created\ndocker images\nStep 2: Save the image to a file\nbash\n# Save the image to a tar file\ndocker save -o mysql-with-data.tar mysql-with-data\nStep 3: Transfer and load on your laptop\nbash\n# On your laptop, load the image\ndocker load -i mysql-with-data.tar\n\n# Run the container\ndocker run -d -p 3306:3306 --name mysql mysql-with-data\nMethod 2: Docker Export/Import (Container snapshot)\nStep 1: Export the container\nbash\n# Export container to tar file\ndocker export mysql -o mysql-container.tar\nStep 2: Import on your laptop\nbash\n# Import the container\ncat mysql-container.tar | docker import - mysql-imported\n\n# Run the imported image\ndocker run -d -p 3306:3306 --name mysql mysql-imported\nMethod 3: Backup and Restore Data (Most Reliable)\nStep 1: Create a SQL dump from your container\nbash\n# Create a complete backup\ndocker exec mysql sh -c \'exec mysqldump --all-databases -uroot -ppassword\' > full-backup.sql\n\n# Or backup specific databases\ndocker exec mysql sh -c \'exec mysqldump -uroot -ppassword your_database\' > database-backup.sql\nStep 2: Transfer the SQL file to your laptop\nStep 3: Restore on your laptop\nbash\n# Start a fresh MySQL container\ndocker run -d -p 3306:3306 --name mysql -e MYSQL_ROOT_PASSWORD=password mysql:8.0\n\n# Wait for MySQL to start, then restore\ndocker exec -i mysql sh -c \'exec mysql -uroot -ppassword\' < full-backup.sql\nMethod 4: Volume Backup (Best for large databases)\nStep 1: Find your MySQL volume\nbash\n# Find volume name\ndocker inspect mysql | grep Source\n\n# Or list volumes\ndocker volume ls\nStep 2: Backup the volume data\nbash\n# Create a backup container that copies the data\ndocker run --rm --volumes-from mysql -v $(pwd):/backup ubuntu tar cvf /backup/mysql-data.tar /var/lib/mysql\nStep 3: Restore on your laptop\nbash\n# Start new MySQL container\ndocker run -d -p 3306:3306 --name mysql -e MYSQL_ROOT_PASSWORD=password mysql:8.0\n\n# Restore the data\ndocker run --rm --volumes-from mysql -v $(pwd):/backup ubuntu bash -c \"cd / && tar xvf /backup/mysql-data.tar\"\nMethod 5: Using Docker Compose (Recommended for Portability)\nStep 1: Create a docker-compose.yml file\nyaml\nversion: \'3.8\'\nservices:\n  mysql:\n    image: mysql:8.0\n    container_name: mysql\n    environment:\n      MYSQL_ROOT_PASSWORD: password\n      MYSQL_DATABASE: your_database\n    ports:\n      - \"3306:3306\"\n    volumes:\n      - mysql_data:/var/lib/mysql\nvolumes:\n  mysql_data:\nStep 2: Backup with compose\nbash\n# Backup data\ndocker-compose down\ntar czf mysql-backup.tar.gz mysql_data/','docker/Docker Commit.txt','Docker Commit');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (113,'On your current machine:\nbash\n# Create backup\ndocker exec mysql sh -c \'exec mysqldump --all-databases -uroot -ppassword\' > mysql-full-backup.sql\n\n# Verify backup file\nhead -n 10 mysql-full-backup.sql\nOn your laptop:\nbash\n# Start fresh MySQL\ndocker run -d -p 3306:3306 --name mysql -e MYSQL_ROOT_PASSWORD=password mysql:8.0\n\n# Wait 30 seconds for MySQL to initialize, then restore\ndocker exec -i mysql sh -c \'exec mysql -uroot -ppassword\' < mysql-full-backup.sql\n\n# Verify restoration\ndocker exec mysql sh -c \'exec mysql -uroot -ppassword -e \"SHOW DATABASES;\"\'\nTransferring the Files\nYou can transfer the backup file using:\n\nUSB drive\n\nCloud storage (Google Drive, Dropbox)\n\nEmail (if file is small)\n\nNetwork transfer\n\nVerification\nAfter transferring, verify your data:\n\nbash\n# Check databases\ndocker exec mysql mysql -uroot -ppassword -e \"SHOW DATABASES;\"\n\n# Check tables in your database\ndocker exec mysql mysql -uroot -ppassword -e \"USE your_database; SHOW TABLES;\"\n\n# Check row counts\ndocker exec mysql mysql -uroot -ppassword -e \"USE your_database; SELECT COUNT(*) FROM your_table;\"\nThe SQL dump method (Method 3) is the most reliable and recommended approach for moving MySQL data between machines!\n\nrun  container\nI\'ll help you run your MySQL container. Based on our previous discussion, here are the commands:\n\nMethod 1: Run MySQL on Default Port (3306) - Use if no conflict\nbash\n# Run MySQL container on port 3306\ndocker run -d \\\n  --name mysql \\\n  -p 3306:3306 \\\n  -e MYSQL_ROOT_PASSWORD=password \\\n  -e MYSQL_ROOT_HOST=\'%\' \\\n  mysql:8.0\n\n# Check if container is running\ndocker ps\n\n# View container logs\ndocker logs mysql\nMethod 2: Run MySQL on Alternative Port (3307) - Use if port 3306 is busy\nbash\n# Run MySQL container on port 3307\ndocker run -d \\\n  --name mysql \\\n  -p 3307:3306 \\\n  -e MYSQL_ROOT_PASSWORD=password \\\n  -e MYSQL_ROOT_HOST=\'%\' \\\n  mysql:8.0\n\n# Check if container is running\ndocker ps\nMethod 3: Run with Persistent Storage (Recommended for data safety)\nbash\n# Create a volume for persistent data\ndocker volume create mysql_data\n\n# Run MySQL with persistent storage\ndocker run -d \\\n  --name mysql \\\n  -p 3306:3306 \\\n  -e MYSQL_ROOT_PASSWORD=password \\\n  -e MYSQL_ROOT_HOST=\'%\' \\\n  -v mysql_data:/var/lib/mysql \\\n  mysql:8.0\nMethod 4: Run with Custom Database\nbash\n# Run MySQL with a specific database pre-created\ndocker run -d \\\n  --name mysql \\\n  -p 3306:3306 \\\n  -e MYSQL_ROOT_PASSWORD=password \\\n  -e MYSQL_DATABASE=myapp \\\n  -e MYSQL_ROOT_HOST=\'%\' \\\n  mysql:8.0\nCheck Container Status\nAfter running any of the above commands, verify:\n\nbash\n# Check if container is running\ndocker ps\n\n# Check container status\ndocker inspect mysql\n\n# View real-time logs\ndocker logs -f mysql\nConnect to MySQL\nOnce the container is running, you can connect:\n\nFrom command line:\nbash\n# Connect to MySQL inside container\ndocker exec -it mysql mysql -uroot -ppassword\n\n# Or connect from host machine\nmysql -h 127.0.0.1 -P 3306 -u root -p\nFrom Windows applications:\nHost: localhost or 127.0.0.1\n\nPort: 3306 (or 3307 if using alternative port)\n\nUsername: root\n\nPassword: password\n\nIf Container Already Exists\nIf you already have a container named \"mysql\", remove it first:\n\nbash\n# Stop and remove existing container\ndocker stop mysql\ndocker rm mysql\n\n# Then run one of the above commands\nQuick One-Liner\nFor a quick start with all the recommended settings:\n\nbash\ndocker run -d --name mysql -p 3306:3306 -e MYSQL_ROOT_PASSWORD=password -e MYSQL_ROOT_HOST=\'%\' -v mysql_data:/var/lib/mysql mysql:8.0\nChoose Method 2 (port 3307) if you already have MySQL running on your Windows machine on port 3306. Otherwise, use Method 1 or Method 3 for persistent storage.\n\nYour MySQL container should now be running and ready to use!','docker/SQL Dump.txt','SQL Dump');
INSERT INTO `template` (`id`, `content`, `path`, `template_name`) VALUES (116,'Method 1: Backup with INSERT queries only (no structure)\nbash\ndocker exec mysql sh -c \'exec mysqldump --all-databases --no-create-info --skip-triggers --compact --complete-insert -uroot -ppassword\' > data-only-backup.sql\nMethod 2: Backup specific database with INSERTs only\nbash\n# Replace \'your_database\' with your actual database name\ndocker exec mysql sh -c \'exec mysqldump your_database --no-create-info --skip-triggers --compact --complete-insert -uroot -ppassword\' > database-data.sql\nMethod 3: Backup with extended INSERTs (more efficient)\nbash\ndocker exec mysql sh -c \'exec mysqldump --all-databases --no-create-info --skip-triggers --extended-insert -uroot -ppassword\' > data-backup.sql\nKey Options Explained:\n--no-create-info : Skip CREATE TABLE statements\n\n--skip-triggers : Skip trigger definitions\n\n--compact : Minimal output (just data)\n\n--complete-insert : Use complete INSERT statements with column names\n\n--extended-insert : Use multi-row INSERT syntax (more efficient)\n\nExample Output:\nThe backup file will contain only INSERT statements like:\n\nsql\nINSERT INTO `users` (`id`, `name`, `email`) VALUES (1, \'John\', \'john@example.com\');\nINSERT INTO `users` (`id`, `name`, `email`) VALUES (2, \'Jane\', \'jane@example.com\');\nIf you want both structure and data but in separate files:\nbash\n# Backup only structure\ndocker exec mysql sh -c \'exec mysqldump --all-databases --no-data -uroot -ppassword\' > structure-only.sql\n\n# Backup only data (INSERTs)\ndocker exec mysql sh -c \'exec mysqldump --all-databases --no-create-info -uroot -ppassword\' > data-only.sql\nVerify your backup:\nbash\n# Check the content of your backup file\nhead -n 20 data-only-backup.sql\n\n# Count the number of INSERT statements\ngrep -c \"INSERT INTO\" data-only-backup.sql\nThis will create a backup file containing only the INSERT queries for your data, without any database structure commands.\n\njust insert\nHere\'s the command to create a backup with only INSERT queries (no structure, no comments, just pure data):\n\nPure INSERT Queries Only\nbash\ndocker exec mysql sh -c \'exec mysqldump --all-databases --no-create-info --skip-triggers --skip-comments --compact --complete-insert -uroot -ppassword\' > pure-inserts.sql\nEven Cleaner Version (Minimal Output)\nbash\ndocker exec mysql sh -c \'exec mysqldump --all-databases --no-create-info --skip-triggers --skip-comments --compact --skip-opt --complete-insert -uroot -ppassword\' > pure-inserts.sql\nFor a Specific Database\nbash\n# Replace \'your_database\' with your actual database name\ndocker exec mysql sh -c \'exec mysqldump your_database --no-create-info --skip-triggers --skip-comments --compact --complete-insert -uroot -ppassword\' > pure-inserts.sql\nWhat This Command Does:\n--no-create-info : No CREATE TABLE statements\n\n--skip-triggers : No trigger definitions\n\n--skip-comments : No comments or metadata\n\n--compact : Minimal output format\n\n--complete-insert : Full INSERT statements with column names\n\n--skip-opt : Skip additional optimization options\n\nExample Output:\nYour pure-inserts.sql file will contain ONLY lines like:\n\nsql\nINSERT INTO `table_name` (`col1`, `col2`, `col3`) VALUES (1, \'value1\', \'value2\');\nINSERT INTO `table_name` (`col1`, `col2`, `col3`) VALUES (2, \'value3\', \'value4\');\nINSERT INTO `table_name` (`col1`, `col2`, `col3`) VALUES (3, \'value5\', \'value6\');\nVerify the Result:\nbash\n# View first few lines\nhead -n 10 pure-inserts.sql\n\n# Check if file contains only INSERT statements\ngrep -v \"INSERT INTO\" pure-inserts.sql | head -n 5\n# (Should return no results if it\'s pure INSERTs)\nThis will give you a clean SQL file containing nothing but INSERT queries for all your data!\n\njust insert for shceme productdb\nHere\'s the command to create only INSERT queries for the productdb schema:\n\nPure INSERT Queries for productdb\nbash\ndocker exec mysql sh -c \'exec mysqldump productdb --no-create-info --skip-triggers --skip-comments --compact --complete-insert -uroot -ppassword\' > productdb-inserts.sql\nEven Cleaner Version (No Extra Output)\nbash\ndocker exec mysql sh -c \'exec mysqldump productdb --no-create-info --skip-triggers --skip-comments --skip-opt --complete-insert -uroot -ppassword\' > productdb-pure-inserts.sql\nIf You Want Extended INSERTs (More Efficient)\nbash\ndocker exec mysql sh -c \'exec mysqldump productdb --no-create-info --skip-triggers --skip-comments --extended-insert -uroot -ppassword\' > productdb-inserts-extended.sql\nVerify the Backup\nbash\n# Check the content\nhead -n 10 productdb-inserts.sql\n\n# Count the INSERT statements\ngrep -c \"INSERT INTO\" productdb-inserts.sql\n\n# See which tables are included\ngrep \"INSERT INTO\" productdb-inserts.sql | sort | uniq\nExample Output:\nYour productdb-inserts.sql file will contain ONLY:\n\nsql\nINSERT INTO `products` (`id`, `name`, `price`, `category`) VALUES (1, \'Laptop\', 999.99, \'Electronics\');\nINSERT INTO `products` (`id`, `name`, `price`, `category`) VALUES (2, \'Mouse\', 25.50, \'Accessories\');\nINSERT INTO `users` (`id`, `username`, `email`) VALUES (1, \'john_doe\', \'john@example.com\');\nINSERT INTO `orders` (`order_id`, `user_id`, `total_amount`) VALUES (1001, 1, 1025.49);\nIf You Want to Backup Specific Tables Only\nbash\n# Backup only specific tables\ndocker exec mysql sh -c \'exec mysqldump productdb table1 table2 table3 --no-create-info --skip-triggers --skip-comments --compact --complete-insert -uroot -ppassword\' > specific-tables-inserts.sql\nThis will create a SQL file containing only the INSERT statements for all data in your productdb database, without any schema structure or other commands.\n\n','docker/Backup mysql.txt','Backup mysql');

